(* [comment removed for export] *)
Ltac kxg_vals :=
  repeat match goal with
  | |- context [ev ?E ?j] =>
      let w := fresh "v" in
      first [ let H := fresh "HR" in kx_range (EVar j) H; set (w := ev E j) in *; clearbody w
            | set (w := ev E j) in *; clearbody w
            | set (w := ev E j) in |- *; clearbody w ]
  end;
  repeat match goal with
  | |- context [edenot ?E ?e] =>
      let w := fresh "u" in
      first [ let H := fresh "HR" in kx_range e H; set (w := edenot E e) in *; clearbody w
            | set (w := edenot E e) in *; clearbody w
            | set (w := edenot E e) in |- *; clearbody w ]
  end.
Ltac kxg_hyp H :=
  repeat match type of H with
  | context [ev ?E ?j] =>
      let w := fresh "v" in
      first [ let H' := fresh "HR" in kx_range (EVar j) H'; set (w := ev E j) in *; clearbody w
            | set (w := ev E j) in *; clearbody w ]
  end;
  repeat match type of H with
  | context [edenot ?E ?e] =>
      let w := fresh "u" in
      first [ let H' := fresh "HR" in kx_range e H'; set (w := edenot E e) in *; clearbody w
            | set (w := edenot E e) in *; clearbody w ]
  end.
Ltac kxg_clear :=
  lazymatch goal with
  | HK : know_ok _ ?E _ _ |- _ =>
      let b := eval unfold E in E in
      repeat match goal with H : context [E] |- _ => clear H end;
      try clear E;
      lazymatch b with kx_env _ ?xs => try clear xs | _ => idtac end
  end.


Ltac w4l := first [lia | rewrite ?Z_to_bv_bv_unsigned; lia
  | rewrite ?Z_to_bv_unsigned, ?bv_wrap_small by (unfold bv_modulus; cbn; lia); lia].


(* [comment removed for export] *)
Definition w4s34_RcA_case : Prop :=
  forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
         (gp tp x5 x8 x9 x10 x12 x13 x17 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x29 x30 x31 : word)
         (P SS n SBL SBH S4 L4 PTR PN U BITS PP OL : Z) (w240 w248 w256 : word),
    PTR = PN + U ->
    w4s_src_ctx RNG mm SS n SBL SBH ->
    n < 2^26 ->
    SS <= S4 ->
    S4 + L4 <= SS + n ->
    rw_cells asegs mm (P + 136) [C8 (Z_to_bv 64 2147450880)] ->
    rw_cells asegs mm (P + 240) [C8 w240] ->
    rw_cells asegs mm (P + 248) [C4 w248] ->
    rw_cells asegs mm (P + 256) [C8 w256] ->
    rng RNG P 496 ->
    0x10007fff8000 <= P ->
    P + 496 <= 2^47 ->
    KXGoM.apart SS n P 496 ->
    S4 < PTR < S4 + 8 ->
    PTR - S4 + 8 <= L4 ->
    0 <= BITS <= 64 ->
    0 <= U <= 8 ->
    S4 <= PN ->
    0x60d000 <= PP ->
    PP < 2^47 ->
    0x60d000 <= OL ->
    OL <= 2^47 ->
    (PP < OL -> forall (mm' : amem) (B' : Z) (cw : word) (y7 y15 y28 y29 y30 y31 : word),
       munch [(P + 240, P + 252); (P + 256, P + 264)] mm mm' ->
       wmono asegs mm mm' ->
       mem_inv asegs mm' ->
       rw_cells asegs mm' (P + 240) [C8 cw] ->
       rw_cells asegs mm' (P + 248) [C4 (Z_to_bv 64 B')] ->
       rw_cells asegs mm' (P + 256) [C8 (Z_to_bv 64 PN)] ->
       B' = BITS - 8 * U ->
       evtF asegs RNG Q (MS (mkR (Z_to_bv 64 OL) (Z_to_bv 64 P) gp tp x5 (Z_to_bv 64 B') y7 x8 x9 x10 (Z_to_bv 64 PP) x12 x13
           cw y15 (Z_to_bv 64 PP) x17 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 y28 y29 y30 y31) F (Z_to_bv 64 0x92a1c)
           fc None mm' (seg_rom asegs))) ->
    (OL <= PP -> forall (mm' : amem) (B' : Z) (cw : word) (y6 y7 y14 y15 y28 y29 y30 y31 : word),
       munch [(P + 240, P + 252); (P + 256, P + 264)] mm mm' ->
       wmono asegs mm mm' ->
       mem_inv asegs mm' ->
       rw_cells asegs mm' (P + 240) [C8 cw] ->
       rw_cells asegs mm' (P + 248) [C4 (Z_to_bv 64 B')] ->
