(* [comment removed for export] *)
Definition w4s34_RcB_case : Prop :=
  forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
         (gp tp x5 x8 x9 x10 x12 x13 x17 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x29 x30 x31 : word)
         (P SS n SBL SBH S4 L4 pt PTR U BITS PP OL : Z) (w240 w248 w256 : word),
    PTR = S4 + pt ->
    w4s_src_ctx RNG mm SS n SBL SBH ->
    n < 2^26 ->
    SS <= S4 ->
    S4 + L4 <= SS + n ->
    rw_cells asegs mm (P + 136) [C8 (Z_to_bv 64 2147450880)] ->
    rw_cells asegs mm (P + 240) [C8 w240] ->
    rw_cells asegs mm (P + 248) [C4 w248] ->
    rw_cells asegs mm (P + 256) [C8 w256] ->
    rng RNG P 496 ->
    0x10007fff8000 <= P ->
    P + 496 <= 2^47 ->
    KXGoM.apart SS n P 496 ->
    1 <= pt <= 7 ->
    pt + 8 <= L4 ->
    0 <= BITS <= 64 ->
    0 <= U <= 8 ->
    PTR - U < S4 ->
    0x60d000 <= PP ->
    PP < 2^47 ->
    0x60d000 <= OL ->
    OL <= 2^47 ->
    (forall (mm' : amem) (B' : Z) (cw : word) (y6 y7 y14 y15 y28 y29 y30 y31 : word),
       munch [(P + 240, P + 252); (P + 256, P + 264)] mm mm' ->
       wmono asegs mm mm' ->
       mem_inv asegs mm' ->
       rw_cells asegs mm' (P + 240) [C8 cw] ->
       rw_cells asegs mm' (P + 248) [C4 (Z_to_bv 64 B')] ->
       rw_cells asegs mm' (P + 256) [C8 (Z_to_bv 64 S4)] ->
       B' = BITS - 8 * pt ->
       evtF asegs RNG Q (MS (mkR (Z_to_bv 64 OL) (Z_to_bv 64 P) gp tp x5 y6 y7 x8 x9 x10 (Z_to_bv 64 PP) x12 x13 y14 y15
           (Z_to_bv 64 PP) x17 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 y28 y29 y30 y31) F (Z_to_bv 64 0x92d7c) fc None
           mm' (seg_rom asegs))) ->
    evtF asegs RNG Q (MS (mkR (Z_to_bv 64 OL) (Z_to_bv 64 P) gp tp x5 (Z_to_bv 64 U) (Z_to_bv 64 S4) x8 x9 x10 (Z_to_bv 64
        PP) x12 x13 (Z_to_bv 64 PTR) (Z_to_bv 64 BITS) (Z_to_bv 64 PP) x17 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27
        (Z_to_bv 64 (PTR - U)) x29 x30 x31) F (Z_to_bv 64 0x9294c) fc None mm (seg_rom asegs)).

